type Account struct {
	ID      string
	Balance int64
	Held    int64
	Frozen  bool
}

type Hold struct {
	ID      string `json:"id"`
	Account string `json:"account"`
	Amount  int64  `json:"amount"`
}

type Entry struct {
	Seq     int    `json:"seq"`
	Account string `json:"account"`
	Delta   int64  `json:"delta"`
	Kind    string `json:"kind"`
}

type Route struct {
	Method  string
	Pattern string
	Handle  func(l *Ledger, w http.ResponseWriter, r *http.Request, params []string)
}

func main() {
	addr := flag.String("addr", ":8080", "listen address")
	flag.Parse()
	l := &Ledger{
		accounts:  map[string]*Account{},
		transfers: map[string]*Transfer{},
		keys:      map[string]*Transfer{},
		holds:     map[string]*Hold{},
	}
	log.Fatal(http.ListenAndServe(*addr, l))
}
